#define MCAN_DBTP       0x0008  /* Data Bit Timing and Prescaler Register */
#define MCAN_TEST       0x000C  /* Test Register */
#define MCAN_RWD        0x0010  /* RAM Watchdog Register */
#define MCAN_CCCR       0x0014  /* CC Control Register */
#define MCAN_BTP        0x0018  /* Bit Timing and Prescaler Register */
#define MCAN_TSCC       0x001C  /* Timestamp Counter Configuration Register */
#define MCAN_TSCV       0x0020  /* Timestamp Counter Value Register */
#define MCAN_TOCC       0x0024  /* Timeout Counter Configuration Register */
