/* MCAN_CCCR Register Bit Fields */
#define MCAN_CCCR_INIT_MASK     BIT(0)  /* Initialization */
#define MCAN_CCCR_CCE_MASK      BIT(1)  /* Configuration Change Enable */
#define MCAN_CCCR_ASM_MASK      BIT(2)  /* Restricted Operation Mode */
#define MCAN_CCCR_CSA_MASK      BIT(3)  /* Clock Stop Acknowledge */
#define MCAN_CCCR_CSR_MASK      BIT(4)  /* Clock Stop Request */
#define MCAN_CCCR_MON_MASK      BIT(5)  /* Bus Monitoring Mode */
#define MCAN_CCCR_DAR_MASK      BIT(6)  /* Disable Automatic Retransmission */
#define MCAN_CCCR_TEST_MASK     BIT(7)  /* Test Mode Enable */
#define MCAN_CCCR_FDOE_MASK     BIT(8)  /* FD Operation Enable */
#define MCAN_CCCR_BRSE_MASK     BIT(9)  /* Bit Rate Switch Enable */
#define MCAN_CCCR_PXHD_MASK     BIT(12) /* Protocol Exception Handling Disable */
#define MCAN_CCCR_EFBI_MASK     BIT(13) /* Edge Filtering during Bus Integration */
#define MCAN_CCCR_NISO_MASK     BIT(14) /* Non ISO Operation */

/* MCAN_BTP Register Bit Fields */
#define MCAN_BTP_TSEG2_POS      0
#define MCAN_BTP_TSEG2_MASK     GENMASK(2, 0)
#define MCAN_BTP_TSEG1_POS      4
#define MCAN_BTP_TSEG1_MASK     GENMASK(7, 4)
#define MCAN_BTP_SJW_POS        8
#define MCAN_BTP_SJW_MASK       GENMASK(9, 8)
#define MCAN_BTP_BRP_POS        16
#define MCAN_BTP_BRP_MASK       GENMASK(25, 16)

/* MCAN_DBTP Register Bit Fields */
#define MCAN_DBTP_DTSEG2_POS    0
#define MCAN_DBTP_DTSEG2_MASK   GENMASK(2, 0)
#define MCAN_DBTP_DTSEG1_POS    4
#define MCAN_DBTP_DTSEG1_MASK   GENMASK(7, 4)
#define MCAN_DBTP_DSJW_POS      8
#define MCAN_DBTP_DSJW_MASK     GENMASK(9, 8)
#define MCAN_DBTP_DBRP_POS      16
#define MCAN_DBTP_DBRP_MASK     GENMASK(20, 16)

/* MCAN_PSR Register Bit Fields */
#define MCAN_PSR_LEC_POS        0
#define MCAN_PSR_LEC_MASK       GENMASK(2, 0)   /* Last Error Code */
#define MCAN_PSR_ACT_POS        3
#define MCAN_PSR_ACT_MASK       GENMASK(4, 3)   /* Activity */
#define MCAN_PSR_EP_MASK        BIT(5)          /* Error Passive */
#define MCAN_PSR_EW_MASK        BIT(6)          /* Error Warning */
#define MCAN_PSR_BO_MASK        BIT(7)          /* Bus_Off */
#define MCAN_PSR_TXBP_MASK      BIT(8)          /* Tx Buffer Pending */
#define MCAN_PSR_RXBP_MASK      BIT(9)          /* Rx Buffer Pending */
#define MCAN_PSR_TDCV_POS       16
#define MCAN_PSR_TDCV_MASK      GENMASK(22, 16) /* Transmitter Delay Compensation Value */

/* MCAN_ECR Register Bit Fields */
#define MCAN_ECR_TEC_POS        0
#define MCAN_ECR_TEC_MASK       GENMASK(7, 0)   /* Transmit Error Counter */
#define MCAN_ECR_REC_POS        8
#define MCAN_ECR_REC_MASK       GENMASK(14, 8)  /* Receive Error Counter */
#define MCAN_ECR_RP_MASK        BIT(15)         /* Error Logging */
#define MCAN_ECR_CEL_POS        16
#define MCAN_ECR_CEL_MASK       GENMASK(23, 16) /* CAN Error Logging */

/* MCAN_IR Register Bit Fields */
#define MCAN_IR_RF0N_MASK       BIT(0)  /* Rx FIFO 0 New Message */
#define MCAN_IR_RF0W_MASK       BIT(1)  /* Rx FIFO 0 Full */
#define MCAN_IR_RF0F_MASK       BIT(2)  /* Rx FIFO 0 Message Lost */
#define MCAN_IR_RF0L_MASK       BIT(3)  /* Rx FIFO 0 Message Lost */
#define MCAN_IR_RF1N_MASK       BIT(4)  /* Rx FIFO 1 New Message */
#define MCAN_IR_RF1W_MASK       BIT(5)  /* Rx FIFO 1 Full */
#define MCAN_IR_RF1F_MASK       BIT(6)  /* Rx FIFO 1 Message Lost */
#define MCAN_IR_RF1L_MASK       BIT(7)  /* Rx FIFO 1 Message Lost */
#define MCAN_IR_HPM_MASK        BIT(8)  /* High Priority Message */
#define MCAN_IR_TC_MASK         BIT(9)  /* Transmission Completed */
#define MCAN_IR_TCR_MASK        BIT(10) /* Transmission Cancellation Finished */
#define MCAN_IR_ELO_MASK        BIT(11) /* Error Logging Overflow */
#define MCAN_IR_EP_MASK         BIT(12) /* Error Passive */
#define MCAN_IR_BO_MASK         BIT(13) /* Bus_Off Status */
#define MCAN_IR_WDI_MASK        BIT(14) /* Watchdog Interrupt */
#define MCAN_IR_PEA_MASK        BIT(15) /* Protocol Error in Arbitration Phase */
#define MCAN_IR_PED_MASK        BIT(16) /* Protocol Error in Data Phase */
#define MCAN_IR_ARA_MASK        BIT(17) /* Access to Reserved Address */
#define MCAN_IR_DRX_MASK        BIT(22) /* Message stored to Dedicated Rx Buffer */
#define MCAN_IR_TOO_MASK        BIT(23) /* Timeout Occurred */
#define MCAN_IR_MRAF_MASK       BIT(24) /* Message RAM Access Failure */
#define MCAN_IR_TSW_MASK        BIT(25) /* Timestamp Wraparound */
#define MCAN_IR_TEFN_MASK       BIT(26) /* Tx Event FIFO New Entry */
#define MCAN_IR_TEFW_MASK       BIT(27) /* Tx Event FIFO Full */
#define MCAN_IR_TEFF_MASK       BIT(28) /* Tx Event FIFO Message Lost */
#define MCAN_IR_TEFL_MASK       BIT(29) /* Tx Event FIFO Message Lost */

/* MCAN_GFC Register Bit Fields */
#define MCAN_GFC_RRFE_MASK      BIT(0)  /* Reject Remote Frames Extended */
#define MCAN_GFC_RRFS_MASK      BIT(1)  /* Reject Remote Frames Standard */
#define MCAN_GFC_ANFE_POS       2
#define MCAN_GFC_ANFE_MASK      GENMASK(3, 2) /* Accept Non-matching Frames Extended */
#define MCAN_GFC_ANFS_POS       4
#define MCAN_GFC_ANFS_MASK      GENMASK(5, 4) /* Accept Non-matching Frames Standard */

/* MCAN_RXF0C/RXF1C Register Bit Fields */
#define MCAN_RXFC_FSA_POS       0
#define MCAN_RXFC_FSA_MASK      GENMASK(15, 0)  /* Rx FIFO Start Address */
#define MCAN_RXFC_FSS_POS       16
#define MCAN_RXFC_FSS_MASK      GENMASK(22, 16) /* Rx FIFO Size */
#define MCAN_RXFC_FWATER_POS    24
#define MCAN_RXFC_FWATER_MASK   GENMASK(30, 24) /* Rx FIFO Watermark */
#define MCAN_RXFC_FOM_MASK      BIT(31)         /* FIFO Operation Mode */

/* MCAN_RXF0S/RXF1S Register Bit Fields */
#define MCAN_RXFS_FFL_POS       0
#define MCAN_RXFS_FFL_MASK      GENMASK(6, 0)   /* Rx FIFO Fill Level */
#define MCAN_RXFS_FGI_POS       8
#define MCAN_RXFS_FGI_MASK      GENMASK(13, 8)  /* Rx FIFO Get Index */
#define MCAN_RXFS_FPI_POS       16
#define MCAN_RXFS_FPI_MASK      GENMASK(21, 16) /* Rx FIFO Put Index */
#define MCAN_RXFS_RF0F_MASK     BIT(24)         /* Rx FIFO Full */
#define MCAN_RXFS_DMS_POS       25
#define MCAN_RXFS_DMS_MASK      GENMASK(26, 25) /* Message Lost */

/* MCAN_RXESC Register Bit Fields */
#define MCAN_RXESC_F0DS_POS     0
#define MCAN_RXESC_F0DS_MASK    GENMASK(2, 0)   /* Rx FIFO 0 Data Field Size */
#define MCAN_RXESC_F1DS_POS     4
#define MCAN_RXESC_F1DS_MASK    GENMASK(6, 4)   /* Rx FIFO 1 Data Field Size */
#define MCAN_RXESC_RBDS_POS     8
#define MCAN_RXESC_RBDS_MASK    GENMASK(10, 8)  /* Rx Buffer Data Field Size */

/* MCAN_TXBC Register Bit Fields */
#define MCAN_TXBC_TBSA_POS      0
