#define MCAN_TXBC_NDTB_MASK     GENMASK(21, 16) /* Number of Dedicated Tx Buffers */
#define MCAN_TXBC_TFQS_POS      24
#define MCAN_TXBC_TFQS_MASK     GENMASK(29, 24) /* Tx FIFO/Queue Size */
#define MCAN_TXBC_TFQM_MASK     BIT(30)         /* Tx FIFO/Queue Mode */

/* MCAN_TXESC Register Bit Fields */
#define MCAN_TXESC_TBDS_POS     0
#define MCAN_TXESC_TBDS_MASK    GENMASK(2, 0)   /* Tx Buffer Data Field Size */

/* MCAN_TXBRP Register Bit Fields */
#define MCAN_TXBRP_TRP_MASK     GENMASK(31, 0)  /* Tx Buffer Request Pending */

/* MCAN_TXBAR Register Bit Fields */
#define MCAN_TXBAR_AR_MASK      GENMASK(31, 0)  /* Add Request */

/* MCAN_TXBCR Register Bit Fields */
#define MCAN_TXBCR_CR_MASK      GENMASK(31, 0)  /* Cancellation Request */

/* MCAN_TXBTO Register Bit Fields */
#define MCAN_TXBTO_TO_MASK      GENMASK(31, 0)  /* Transmission Occurred */

/* MCAN_TXEFC Register Bit Fields */
#define MCAN_TXEFC_EFSA_POS     0
#define MCAN_TXEFC_EFSA_MASK    GENMASK(15, 0)  /* Event FIFO Start Address */
#define MCAN_TXEFC_EFS_POS      16
#define MCAN_TXEFC_EFS_MASK     GENMASK(21, 16) /* Event FIFO Size */
#define MCAN_TXEFC_EFWM_POS     24
#define MCAN_TXEFC_EFWM_MASK    GENMASK(30, 24) /* Event FIFO Watermark */

/* MCAN_TXEFS Register Bit Fields */
#define MCAN_TXEFS_EFFL_POS     0
#define MCAN_TXEFS_EFFL_MASK    GENMASK(5, 0)   /* Event FIFO Fill Level */
#define MCAN_TXEFS_EFGI_POS     8
#define MCAN_TXEFS_EFGI_MASK    GENMASK(12, 8)  /* Event FIFO Get Index */
#define MCAN_TXEFS_EFPI_POS     16
#define MCAN_TXEFS_EFPI_MASK    GENMASK(20, 16) /* Event FIFO Put Index */
#define MCAN_TXEFS_EFFF_MASK    BIT(24)         /* Event FIFO Full */
#define MCAN_TXEFS_TEFL_MASK    BIT(25)         /* Event FIFO Message Lost */

/* MCAN Message RAM Offsets */
#define MCAN_MR_STD_FILTER_OFFSET       0
#define MCAN_MR_EXT_FILTER_OFFSET       (MCAN_MR_STD_FILTER_OFFSET + \
                                         CONFIG_CAN_MCAN_STD_FILTER_NUM * 4)
#define MCAN_MR_RX_FIFO0_OFFSET         (MCAN_MR_EXT_FILTER_OFFSET + \
                                         CONFIG_CAN_MCAN_EXT_FILTER_NUM * 8)
#define MCAN_MR_RX_FIFO1_OFFSET         (MCAN_MR_RX_FIFO0_OFFSET + \
                                         CONFIG_CAN_MCAN_RX_FIFO0_NUM * \
                                         MCAN_RX_FIFO0_ELEMENT_SIZE)
#define MCAN_MR_RX_BUFFER_OFFSET        (MCAN_MR_RX_FIFO1_OFFSET + \
                                         CONFIG_CAN_MCAN_RX_FIFO1_NUM * \
                                         MCAN_RX_FIFO1_ELEMENT_SIZE)
#define MCAN_MR_TX_EVENT_FIFO_OFFSET    (MCAN_MR_RX_BUFFER_OFFSET + \
                                         CONFIG_CAN_MCAN_RX_BUFFER_NUM * \
                                         MCAN_RX_BUFFER_ELEMENT_SIZE)
#define MCAN_MR_TX_BUFFER_OFFSET        (MCAN_MR_TX_EVENT_FIFO_OFFSET + \
                                         CONFIG_CAN_MCAN_TX_EVENT_FIFO_NUM * 8)

/* MCAN Message RAM Element Sizes (in bytes) */
#define MCAN_STD_FILTER_ELEMENT_SIZE    4
#define MCAN_EXT_FILTER_ELEMENT_SIZE    8
#define MCAN_TX_EVENT_ELEMENT_SIZE      8

/* Data field size to element size mapping */
static const uint8_t dlc_to_bytes[] = {0, 1, 2, 3, 4, 5, 6, 7, 8, 12, 16, 20, 24, 32, 48, 64};
static const uint8_t bytes_to_dlc[] = {
    0, 1, 2, 3, 4, 5, 6, 7, 8, /* 0-8 bytes */
    9, /* 9-12 bytes */
    10, /* 13-16 bytes */
    11, /* 17-20 bytes */
    12, /* 21-24 bytes */
    13, /* 25-32 bytes */
    14, /* 33-48 bytes */
    15  /* 49-64 bytes */
};

#define MCAN_MAX_DATA_LENGTH 64

/* Helper to convert data length code to actual data length in bytes */
static inline uint8_t mcan_dlc_to_bytes(uint8_t dlc)
{
    if (dlc > 15) {
        return 0; /* Invalid DLC */
    }
    return dlc_to_bytes[dlc];
}

/* Helper to convert actual data length in bytes to data length code */
static inline uint8_t mcan_bytes_to_dlc(uint8_t bytes)
{
    if (bytes > MCAN_MAX_DATA_LENGTH) {
        return 15; /* Max DLC */
    }
    if (bytes > 8) {
        /* For CAN FD, map to the next higher DLC value */
        if (bytes <= 12) {
            return 9;
        } else if (bytes <= 16) {
            return 10;
        } else if (bytes <= 20) {
            return 11;
        } else if (bytes <= 24) {
            return 12;
        } else if (bytes <= 32) {
            return 13;
        } else if (bytes <= 48) {
            return 14;
        } else { /* bytes <= 64 */
            return 15;
        }
    }
    return bytes_to_dlc[bytes];
}

/*
 * MCAN Message RAM access functions
 */
static inline uint32_t mcan_read_msg_ram(const struct can_mcan_config *config, uint32_t offset)
{
    return sys_read32(config->message_ram_base + offset);
}

static inline void mcan_write_msg_ram(const struct can_mcan_config *config, uint32_t offset,
                                      uint32_t val)
{
    sys_write32(val, config->message_ram_base + offset);
}

/*
 * MCAN Register access functions
 */
static inline uint32_t mcan_read_reg(const struct can_mcan_config *config, uint32_t offset)
{
    return sys_read32(config->base + offset);
}

static inline void mcan_write_reg(const struct can_mcan_config *config, uint32_t offset,
                                  uint32_t val)
{
    sys_write32(val, config->base + offset);
}

static inline void mcan_set_reg_bit(const struct can_mcan_config *config, uint32_t offset,
                                    uint32_t mask)
{
    sys_set_bit(config->base + offset, mask);
}

static inline void mcan_clear_reg_bit(const struct can_mcan_config *config, uint32_t offset,
                                      uint32_t mask)
{
    sys_clear_bit(config->base + offset, mask);
}

static inline void mcan_update_reg(const struct can_mcan_config *config, uint32_t offset,
                                   uint32_t mask, uint32_t val)
{
    sys_write32((mcan_read_reg(config, offset) & ~mask) | (val & mask), config->base + offset);
}

static int mcan_set_timing(const struct device *dev, const struct can_timing *timing)
{
    const struct can_mcan_config *config = dev->config;
    uint32_t btp_reg = 0;

    if (timing->sjw > 3 || timing->prop_seg > 16 || timing->phase_seg1 > 16 ||
        timing->phase_seg2 > 8 || timing->prescaler > 1024) {
        return -EINVAL;
    }

    btp_reg |= FIELD_PREP(MCAN_BTP_TSEG2_MASK, timing->phase_seg2 - 1);
    btp_reg |= FIELD_PREP(MCAN_BTP_TSEG1_MASK, timing->prop_seg + timing->phase_seg1 - 1);
    btp_reg |= FIELD_PREP(MCAN_BTP_SJW_MASK, timing->sjw - 1);
    btp_reg |= FIELD_PREP(MCAN_BTP_BRP_MASK, timing->prescaler - 1);

    mcan_write_reg(config, MCAN_BTP, btp_reg);

    return 0;
}

#ifdef CONFIG_CAN_FD_MODE
static int mcan_set_timing_data(const struct device *dev, const struct can_timing *timing_data)
{
    const struct can_mcan_config *config = dev->config;
    uint32_t dbtp_reg = 0;

    if (timing_data->sjw > 3 || timing_data->prop_seg > 16 || timing_data->phase_seg1 > 16 ||
        timing_data->phase_seg2 > 8 || timing_data->prescaler > 32) {
        return -EINVAL;
    }

    dbtp_reg |= FIELD_PREP(MCAN_DBTP_DTSEG2_MASK, timing_data->phase_seg2 - 1);
    dbtp_reg |= FIELD_PREP(MCAN_DBTP_DTSEG1_MASK, timing_data->prop_seg + timing_data->phase_seg1 - 1);
    dbtp_reg |= FIELD_PREP(MCAN_DBTP_DSJW_MASK, timing_data->sjw - 1);
    dbtp_reg |= FIELD_PREP(MCAN_DBTP_DBRP_MASK, timing_data->prescaler - 1);

    mcan_write_reg(config, MCAN_DBTP, dbtp_reg);

    return 0;
}
#endif /* CONFIG_CAN_FD_MODE */

static int mcan_set_mode(const struct device *dev, enum can_mode mode)
{
    const struct can_mcan_config *config = dev->config;
    struct can_mcan_data *data = dev->data;
    uint32_t cccr_reg;
    k_timeout_t timeout = K_MSEC(100);
    k_ticks_t start_ticks;

    k_mutex_lock(&data->mtx, K_FOREVER);

    /* Request initialization mode to change configuration */
    cccr_reg = mcan_read_reg(config, MCAN_CCCR);
    cccr_reg |= MCAN_CCCR_INIT_MASK;
    mcan_write_reg(config, MCAN_CCCR, cccr_reg);

    /* Wait for initialization acknowledge */
    start_ticks = k_uptime_ticks();
    while (!(mcan_read_reg(config, MCAN_CCCR) & MCAN_CCCR_INIT_MASK)) {
        if (k_uptime_ticks() - start_ticks > timeout.ticks) {
            LOG_ERR("Failed to enter init mode in set_mode (timeout)");
            k_mutex_unlock(&data->mtx);
            return -ETIMEDOUT;
        }
        k_sleep(K_MSEC(1));
    }

    /* Enable configuration change */
    cccr_reg |= MCAN_CCCR_CCE_MASK;
    mcan_write_reg(config, MCAN_CCCR, cccr_reg);

    /* Clear all mode bits first */
    cccr_reg &= ~(MCAN_CCCR_MON_MASK | MCAN_CCCR_DAR_MASK |
#ifdef CONFIG_CAN_FD_MODE
                  MCAN_CCCR_FDOE_MASK | MCAN_CCCR_BRSE_MASK |
#endif /* CONFIG_CAN_FD_MODE */
                  0);

    if (mode & CAN_MODE_LOOPBACK) {
        /* Loopback mode is handled by TEST register */
        mcan_set_reg_bit(config, MCAN_CCCR, MCAN_CCCR_TEST_MASK);
        mcan_update_reg(config, MCAN_TEST, GENMASK(6, 4), FIELD_PREP(GENMASK(6, 4), 0x2)); /* LBCK */
    } else {
        mcan_clear_reg_bit(config, MCAN_CCCR, MCAN_CCCR_TEST_MASK);
    }

    if (mode & CAN_MODE_LISTENONLY) {
        cccr_reg |= MCAN_CCCR_MON_MASK;
    }

    if (mode & CAN_MODE_NO_ACK) {
        cccr_reg |= MCAN_CCCR_DAR_MASK;
    }

#ifdef CONFIG_CAN_FD_MODE
    if (mode & CAN_MODE_FD) {
        cccr_reg |= MCAN_CCCR_FDOE_MASK;
    }

    if (mode & CAN_MODE_BRS) {
        cccr_reg |= MCAN_CCCR_BRSE_MASK;
    }
#endif /* CONFIG_CAN_FD_MODE */

    mcan_write_reg(config, MCAN_CCCR, cccr_reg);

    /* Exit initialization mode */
    cccr_reg &= ~MCAN_CCCR_INIT_MASK;
    mcan_write_reg(config, MCAN_CCCR, cccr_reg);


